"""Render the OLR forensic evidence as a self-contained, reviewable report."""
from pathlib import Path
from html import escape
from html.parser import HTMLParser
import base64
import json

REPO=Path(__file__).resolve().parents[1]
ROOT=REPO/'data/backtests/analysis/olr_round1_oos_review_20261010'
def read(name): return json.loads((ROOT/name).read_text(encoding='utf-8'))
def f(v,d=2): return f'{v:,.{d}f}'
def table(headers,rows):
    return '<div class="table"><table><thead><tr>'+''.join('<th>'+escape(str(x))+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def p(text):return '<p>'+text+'</p>'


def main():
    d=read('diagnostics.json');old=read('mechanism_diagnostics.json');cal=read('calendar_subperiods.json')
    comps=read('comparisons.json');support=read('candidate_support.json');prov=read('provenance.json')
    byid={x['candidate_id']:x for x in comps}
    guards=[x for x in comps if x['label'].startswith('completed_bar_loss_guard')]
    assert len(guards)==3 and read('replays/completion.json')['full_native_audits']==6
    passing=[x for x in comps if x['passes_registered_gates']]
    new_audits=6+(2 if (ROOT/'replays/interaction_completion.json').exists() else 0)+(read('replays/stress_completion.json')['full_native_audits'] if (ROOT/'replays/stress_completion.json').exists() else 0)
    body='<h1>OLR round 1: why OOS performance deteriorated</h1>'
    body+=p('<strong>Evidence as of '+escape(prov['asof_utc'])+'.</strong> IS: 7 August 2025–31 March 2026. OOS: 1 April–10 July 2026. Both start with ₩100 million in cash. All percentage-point comparisons refer to complete native account replays; the formerly OOS period is now development data.')
    body+=p('<strong>The discrepancy is real, but it is not a collapse in win rate.</strong> The strongest evidence points to a reversal in the relationship between position size and realized payoff, more severe adverse price paths, and much thinner opportunity supply in weak markets. A concentrated rank-based allocator and an exit rule that only protects sufficiently profitable trades amplify those changes. Historical-context defects exist, but the verified continuity repair did not change baseline P&amp;L.')
    body+=p(f'This review authenticated {len(comps)} completed paired configurations, including the saved control, by checking completion-file hashes, native audit verdicts, terminal state, and independent NAV/P&amp;L/drawdown reconciliation. It ran <strong>{new_audits} new full-audit replays</strong>: three predeclared completed-bar loss guards across both windows, plus the adaptive interaction and matched stress evaluations recorded below. {len(passing)} configurations meet every existing research acceptance gate under baseline execution assumptions. The larger registered search is incomplete; this report does not claim a global optimum or independently validated improvement.')
    if passing:
        best=max(passing,key=lambda x:(min(x['train_gain_pp'],x['oos_gain_pp']),x['oos_gain_pp']))
        body+=p('<strong>Strongest eligible historical result:</strong> '+escape(best['label'])+f' returns {f(best["train_return_pct"])}% IS and {f(best["oos_return_pct"])}% OOS, changes of {f(best["train_gain_pp"])}pp and {f(best["oos_gain_pp"])}pp. OOS maximum drawdown is {f(best["oos_drawdown_pct"])}%. This is a tested research successor, with selection and execution-model limitations described below.')
    body+='<img alt="Performance paths, rank contributions, calendar attribution and paired experiments" src="data:image/png;base64,'+base64.b64encode((ROOT/'diagnostic_overview.png').read_bytes()).decode()+'">'
    body+='<h2>1. Establish the correct comparison</h2>'
    rows=[]
    metrics=[('Net account return','return_pct',False),('Maximum bar-level MTM drawdown','drawdown_pct',False),('Closed position groups','trades',False),('Exchange sessions','sessions',False)]
    for label,key,_ in metrics:rows.append([label,f(d['train']['result'][key]),f(d['oos']['result'][key])])
    rows += [
        ['Win rate',f(old['train']['win_rate']*100)+'%',f(old['oos']['win_rate']*100)+'%'],
        ['Profit factor',f(d['train']['result']['metrics']['profit_factor']),f(d['oos']['result']['metrics']['profit_factor'])],
        ['Mean winning P&L, KRW',f(old['train']['average_win'],0),f(old['oos']['average_win'],0)],
        ['Mean losing P&L, KRW',f(old['train']['average_loss'],0),f(old['oos']['average_loss'],0)],
        ['Mean win / mean loss',f(old['train']['payoff_ratio']),f(old['oos']['payoff_ratio'])],
        ['Break-even win rate at observed dollar payoffs',f(old['train']['break_even_win_rate']*100)+'%',f(old['oos']['break_even_win_rate']*100)+'%'],
        ['Trades per 21 sessions',f(old['train']['trades_per_21_sessions']),f(old['oos']['trades_per_21_sessions'])],
        ['Days with entries',old['train']['active_days'],old['oos']['active_days']],
        ['Selected candidates per entry-eligible session',f(old['train']['funnel_per_entry_session']['final_candidate_rows']),f(old['oos']['funnel_per_entry_session']['final_candidate_rows'])],
        ['Mean entry notional, KRW million',f(d['train']['entry_notional_mean']/1e6),f(d['oos']['entry_notional_mean']/1e6)],
        ['Equal-weight mean trade net return',f(d['train']['equal_weight_trade_net_return_pct'],3)+'%',f(d['oos']['equal_weight_trade_net_return_pct'],3)+'%'],
        ['Notional-weighted mean trade net return',f(d['train']['notional_weighted_trade_net_return_pct'],3)+'%',f(d['oos']['notional_weighted_trade_net_return_pct'],3)+'%'],
    ]
    body+=table(['Metric','IS','OOS'],rows)
    body+=p('The OOS interval is shorter, so +55.05% versus −3.33% alone exaggerates the visual distance between the windows. However, the deterioration survives a length-matched check: the 88 overlapping 69-session slices of the IS NAV path returned between +5.80% and +45.25%, with a median of +17.85%, and contained 78–99 entries versus 47 OOS. Those slices share observations and inherit prior account wealth and positions; they are descriptive comparisons, not 88 independent tests or freshly initialized replays.')
    body+=p('The official drawdown uses every retained intraday mark. OOS peaked at ₩133.818 million on 15 May at 09:00 KST and troughed at ₩94.794 million on 9 July at 12:15, a 29.16% decline. Month-end or daily-close charts miss that intraday peak. Daily-close monthly drawdowns in the calendar appendix must not replace the official bar-level metric.')
    body+=table(['OOS month','NAV return','Entries','Prior-20d universe mean return*','Mean breadth*'],[[m,f(v['return_pct'])+'%',v['entries'],f(d['oos']['monthly_funnel'][m]['mean_universe_prior_20d_return_pct'])+'%',f(d['oos']['monthly_funnel'][m]['mean_breadth_pct'])+'%'] for m,v in cal['oos']['months'].items()])
    body+=p('*These are averages of the strategy’s dated, prior-data market context across entry-eligible sessions, not a realized index benchmark. April–May gained 16.12% in the continuous account; June–July then lost 16.75% of the wealth entering June. These compounded segments reconcile to −3.33%. They should not be added arithmetically or replaced with a separately reset June-only account.')
    body+='<h2>2. The largest economic problem: concentration meets adverse payoffs</h2>'
    body+=p('The strategy retained a high hit rate. What failed was the payoff received per unit of capital. Average dollar loss increased from ₩0.388 million to ₩1.897 million, about 4.89 times; average dollar win increased only about 1.58 times. The empirical break-even win rate rose from 26.74% to 53.04%, above the achieved 51.06%. On percentage returns, average winners rose from +3.70% to +6.33%, while average losers worsened from −2.14% to −4.46%. The lower 5th percentile of trade returns worsened from −4.02% to −9.64%.')
    body+=p('The equal-weight mean trade net return actually improved from +0.681% to +1.047%. But the notional-weighted return fell from +1.294% to −0.217%. The mean position was 35.1% larger in OOS despite fewer trades. Rank 1 generated +₩36.025 million IS and −₩18.009 million OOS, while OOS ranks 2 and 3 contributed +₩11.224 million and +₩5.609 million. These observations identify the allocation/outcome relationship as a central diagnostic, not merely insufficient signal accuracy.')
    body+=p('An exact descriptive identity makes the effect measurable: total P&amp;L = trade count × [mean entry notional × mean trade return + covariance(entry notional, trade return)]. IS splits into +₩28.972 million from the first term and +₩26.075 million from the covariance term. OOS splits into +₩16.060 million and −₩19.387 million. This is an accounting decomposition of the executed positions, including path-dependent sizing; it does not show what an executable equal-weight portfolio would have earned.')
    body+=p('The configuration permits 65% of equity in one name, rank decay 1.5, target gross exposure 1.2, and a single selected candidate. The gross target is a requested allocation budget, not proof that the account always reaches 120% exposure. As the candidate pool thins, capital can remain concentrated in its first eligible name. Ranking is relative: the best surviving candidate in a weak session need not have a strong absolute expected return. A volatility- and regime-insensitive rank can therefore allocate the most capital to an unusually fragile opportunity.')
    body+=p('The concentration change also appears directly in the ledger: 18 of 29 active OOS entry dates had only one new position, versus 40 of 88 IS entry dates (62.1% versus 45.5%). Mean entry notional divided by the preceding session’s closing NAV rose from approximately 21.5% to 29.8%. This latter ratio is a descriptive prior-close exposure measure, not the exact sizing-time equity denominator or a position-limit audit.')
    worst=old['oos']['worst_trades'][:3]
    body+=table(['Entry / symbol','Rank','Entry notional, ₩m','Trade net return','Loss, ₩m','Exit'],[[x['entry_fill_time'][:10]+' / '+x['symbol'],x['candidate_rank'],f(x['entry_notional']/1e6),f(x['net_return_on_entry_pct'])+'%',f(x['net_pnl']/1e6),x['exit_reason']] for x in worst])
    body+=p('The two June trades alone lost ₩20.707 million, 47.45% of all OOS losing-trade P&amp;L. Neither received a recycled quantity top-up. Blaming the conditional recycling overlay for these two losses would therefore confuse the overlay with the underlying 65% rank-one sizing policy. Removing those trades arithmetically leaves +₩17.379 million, but that is not an executable repair. Removing the two best trades instead leaves −₩15.464 million. Both sides of the tail matter.')
    body+='<h2>3. The exit has an unprotected region</h2>'
    body+=p('Hard stops are disabled. The active MFE-fade exit starts only after maximum favorable excursion reaches one original risk unit, with a giveback gap of 1.25 risk units and floor zero. A trade that never first becomes sufficiently profitable can keep deteriorating until the next-close exit. The two worst June trades reached only about 0.179R and 0.022R of MFE; the large May 27 loss reached about 0.236R. The protective profit-taking rule was therefore never armed for them.')
    body+=p('Much of the damage occurred after the next open, so overnight gaps are only part of the mechanism. For 403870, the first overnight gap was −3.59%, followed by approximately −17.68% from the next open to its recorded exit price. For 055550, the gap was −2.60%, followed by approximately −7.31%. These are observed path decompositions, not a promise that a stop could have filled at a selected threshold.')
    body+=p('The retained capacity contract supports market-open and auction fills, not intrabar protective-stop or limit-target fills. Consequently the historical hard-stop toggle was marked unsupported and cannot be cited as successful protection. This review instead tested the existing completed-bar failed-followthrough exit: after at least one held completed bar, exit if close is below entry by 0.4/0.8/1.2 original ATR-based risk units and prior MFE is below 4R. It retains the incumbent MFE-fade rule and uses the native next-open execution and full audits. The 4R clause makes it a conditional loss guard, not an unconditional guaranteed stop.')
    body+=p('Here R is the native original per-share risk denominator. With hard stops disabled, entry metadata uses max(daily ATR, 0.5% of the submission-bar close, ₩1); position evaluation additionally floors it at 0.1% of the actual entry price. The trigger compares the completed close with the filled entry price using that denominator. Thus “1.2R” is precise; describing it as an always-exact 1.2×ATR stop would omit the price floors and execution delay. The patch changes only the exit-plan mapping and retains every other round-1 mutation.')
    body+=table(['New loss guard','IS return','OOS return','IS DD','OOS DD','IS / OOS trades','Pass all research gates'],[[x['label'].split('loss')[-1],f(x['train_return_pct'])+'%',f(x['oos_return_pct'])+'%',f(x['train_drawdown_pct'])+'%',f(x['oos_drawdown_pct'])+'%',str(x['train_trades'])+' / '+str(x['oos_trades']),str(x['passes_registered_gates'])] for x in sorted(guards,key=lambda x:x['label'])])
    body+=p('Interpret this experiment as a test of an executable mitigation mechanism. A gain in OOS accompanied by a large IS loss is a risk/return trade-off, not satisfaction of the stated objective. More frequent exits also change cash availability, later entries and compounding, which is why full native account replays are required. A rule that sells every losing position early can also sell the temporary pullbacks from which the original strategy earns its best returns.')
    body+=p('The intermediate 0.8R guard is a concrete research improvement: +52.4251% IS and +6.5205% OOS, with drawdowns 8.8242% and 20.0301%, and 180/47 trades. It changes 20 OOS issuer-days, with ten positions ultimately labeled failed-followthrough exits. The 055550 exit advances to June 8 at 09:45, reducing its account loss from ₩7.478 million to ₩3.071 million; the 403870 exit advances to June 16 at 09:05, reducing its loss from ₩13.228 million to ₩6.048 million. Actual execution still suffers gaps and price deterioration: these are not stop-price fills.')
    body+=p('The wider 1.2R guard returns +54.5234% IS and +4.6689% OOS. Relative to baseline that is only −0.5232pp IS and +7.9966pp OOS; drawdowns are 7.5181% and 22.4104%, with 178/47 trades. It preserves 99.663% of baseline terminal IS wealth and approximately 99.05% of IS net profit. The 0.8R variant offers greater loss containment at a higher IS opportunity cost; the 1.2R variant is preferable if IS preservation is the primary tie-breaker. Neither dominates the other across all objectives.')
    body+=p('For the 1.2R guard, 15 OOS issuer-days change, including later position-size effects. Its two largest positive contributions supply 81.74% of all positive attributed gains, and its five-session paired OOS bootstrap interval is approximately −2.99pp to +18.03pp. The point-estimate improvement is substantial and the IS sacrifice small; the uncertainty remains material because this is a short, selected historical sample.')
    body+=p('The 0.8R guard also has concentrated support: the two largest improvements account for 85.49% of positive attributed OOS gains. Excluding them arithmetically changes the +₩9.848 million improvement to −₩1.740 million. The paired five-session bootstrap uplift interval is approximately −4.60pp to +23.26pp, with IS approximately −13.55pp to +14.99pp. This supports the diagnosed tail-control mechanism but does not establish a reliably higher average future return. A successful historical gate is weaker evidence than independent prospective qualification.')
    if (ROOT/'replays/interaction_completion.json').exists():
        ic=read('replays/interaction_completion.json')['candidate_id'];reg=read('replays/interaction_registration.json');x=byid[ic]
        cells=[('Baseline',byid[reg['baseline_id']]),('Wider extension only',byid[reg['wider_only_id']]),('Selected guard only',byid[reg['guard_only_id']]),('Combined',x)]
        body+='<h3>One complementary factorial test</h3>'
        body+=p('After the three guard results, one additional configuration combined the best eligible guard with the previously tested wider entry VWAP-extension limit (2.5% → 999%, effectively disabling that extension gate). This is explicitly adaptive development. The motivation is complementary: the entry change alone raises IS return but harms OOS, while the guard addresses post-entry loss tails. Both single-change controls already exist, so the four-cell comparison distinguishes their joint interaction from simply adding gains.')
        body+=table(['Factorial cell','IS return','OOS return','IS DD','OOS DD'],[[label,f(z['train_return_pct'])+'%',f(z['oos_return_pct'])+'%',f(z['train_drawdown_pct'])+'%',f(z['oos_drawdown_pct'])+'%'] for label,z in cells])
        interactions={w:x[w+'_return_pct']-byid[reg['wider_only_id']][w+'_return_pct']-byid[reg['guard_only_id']][w+'_return_pct']+byid[reg['baseline_id']][w+'_return_pct'] for w in ('train','oos')}
        body+=p(f'The non-additive interaction is {f(interactions["train"])}pp IS and {f(interactions["oos"])}pp OOS. The combined policy passes all inherited gates: <strong>{x["passes_registered_gates"]}</strong>. This single extra cell does not complete the larger search or justify further unrecorded threshold tuning.')
        body+=p(f'Its IS drawdown increases by {f(x["train_drawdown_pct"]-byid[reg["baseline_id"]]["train_drawdown_pct"])}pp. The inherited research ceiling allows only +2pp; that is a secondary constraint beyond the user’s explicit return objective. Improvement in both window returns and qualification under all risk/activity gates are reported separately, so a return improvement is not concealed by an additional research criterion.')
        if x['oos_gain_pp']<0:
            body+=p(f'<strong>Reject this interaction.</strong> It sacrifices {f(-x["oos_gain_pp"])}pp of OOS return relative to baseline despite improving IS. The entry expansion introduces adverse exposures that the chosen guard does not offset. The failure is economic, independently of the additional drawdown gate; it is not a successful two-window improvement.')
    if (ROOT/'replays/stress_completion.json').exists():
        selected_id=read('replays/stress_completion.json')['selected'];sr=read('replays/stress_results.json')
        body+='<h3>Matched execution stress</h3>'
        body+=p('The strongest eligible policy under the registered ranking was rerun against the original control at 0.5% participation (half baseline) and 15bp OLR slippage (versus 5bp), retaining 2bp commission and 20bp modeled sell tax. Each result below passes its full native audit. This tests execution-assumption sensitivity, not live liquidity availability.')
        baseline_id=read('replays/candidate_plan.json')['baseline_id']
        body+=table(['Policy','Window','Stressed return','Stressed DD','Trades'],[['Control' if z['candidate_id']==baseline_id else 'Selected research successor' if z['candidate_id']==selected_id else 'Return-improving interaction / risk trade-off',z['window'],f(z['return_pct'])+'%',f(z['drawdown_pct'])+'%',z['trades']] for z in sr])
        stress_by={(z['candidate_id'],z['window']):z for z in sr}
        stress_gain={w:stress_by[selected_id,w]['return_pct']-stress_by[baseline_id,w]['return_pct'] for w in ('train','oos')}
        body+=p(f'<strong>Stress changes the assessment.</strong> The selected guard changes matched stressed IS return by {f(stress_gain["train"],4)}pp and OOS return by {f(stress_gain["oos"],4)}pp. Under stress its IS loss exceeds the inherited 3pp preservation limit, although only narrowly. The baseline-assumption acceptance verdict therefore does not extend unchanged to execution stress. The guard is a useful mechanism candidate, not a universally superior or fully qualified replacement; stronger execution robustness remains unresolved.')
        body+=p('Candidate: <code>'+escape(selected_id)+'</code>. Read the stressed treatment relative to its stressed control; comparing a stressed successor against an unstressed baseline would misstate the improvement. Different capital sizes and a no-upward-compounding replay were not added in this follow-up, so those remain material qualification limits.')
    body+='<h2>4. Opportunity scarcity is real, and precedes April</h2>'
    body+=p('There are 154 entry-eligible IS snapshots and 67 OOS snapshots; the final two exchange sessions in each replay are reserved for liquidation. The OOS research-stage pool fell from 13.75 to 10.06 candidates per eligible session; final candidates fell from 2.312 to 1.104. Native trade frequency fell 39.6%, from 23.69 to 14.30 per 21 sessions. Conversion from final candidate rows to executed positions rose from 49.4% to 63.5%, so a worse aggregate confirmation/fill conversion rate is not the principal explanation. These ratios are descriptive because positions, slots and cash interact.')
    body+=p('March is especially revealing: 136 first-stage candidates reached the afternoon evaluation, yet no final candidate or entry survived. Thus the weak-market inactivity was already present inside IS. In OOS, June had 112 first-stage candidates, nine final candidates and four trades; July had ten, five and four during six entry-eligible sessions. The two July liquidation-only days should not be counted as missing entry opportunities.')
    body+=table(['Recorded rejection','IS / eligible symbol-days','OOS / eligible symbol-days','Interpretation'],[
        ['Sector participation below floor','11,766 / 15,862 = 74.18%','5,127 / 6,901 = 74.29%','Large bottleneck in both; its aggregate rejection rate barely changes.'],
        ['Trend broken','2,714 / 15,862 = 17.11%','2,429 / 6,901 = 35.20%','A substantial deterioration in trend context.'],
        ['Parent 20d return outside bounds','161 / 15,862 = 1.01%','565 / 6,901 = 8.19%','More candidates encounter the parent-return gate.'],
        ['Final score-band miss','94 IS rows','11 OOS rows','Small relative to upstream rejection counts.'],
    ])
    body+=p('Reasons overlap, and upstream rejection can prevent downstream evaluation. A sole recorded failure isolates one recorded gate, not a trade that would certainly execute. In particular, deleting the parent-return setting reproduced the baseline because deletion restored a default; the −24% perturbation also left executions unchanged. Counts alone do not establish that loosening this threshold creates profitable trades. Disabling data-quality checks to raise activity would invalidate the comparison.')
    body+=p('The regime mix shifts from 18.8% risk-off entry sessions IS to 49.3% OOS. The strategy’s mean universe breadth was about 79.15% in February, 29.84% in March, 66.46% in April and 27.28% in June. The long pullback/recovery setup had many more favorable opportunities in January–February. Those two months contributed about ₩46.141 million of calendar NAV growth, 83.82% of total IS net profit. OOS trades in broad-risk-on context earned +₩15.342 million; mixed and risk-off trades lost ₩11.000 million and ₩7.670 million. This supports a regime interaction hypothesis, but the small cohorts do not prove that banning every weak-regime trade is optimal.')
    body+='<h2>5. Costs, model assumptions and source integrity</h2>'
    body+=p('Explicit charges were ₩10.353 million IS and ₩3.683 million OOS; modeled slippage is already embedded in fill prices. Gross price P&amp;L was +₩65.399 million IS and only +₩0.356 million OOS. Costs turned near-flat OOS gross performance into a loss, but the gross edge had already collapsed. Explicit charges per unit of entry turnover were approximately 24 basis points in both windows. There is no evidence here of an OOS fee-rate shock; reducing the modeled costs is not a structural solution.')
    body+=p('Both controls pass the retained execution audit with no same-bar fills, forced replay closes, rejected orders, or terminal inventory. I independently reconciled trade P&amp;L to terminal NAV and recalculated bar-level drawdowns from the saved equity arrays. Source provenance, consumed-prefix completeness, dated references and price/share basis are marked passed by the native receipts. These are validations against the retained historical research contract, not independent verification of every market print or a live fill guarantee.')
    body+=p('The execution model uses declared 1% participation, prior contiguous bar volume for opening capacity, and actual closing-auction events. Its receipt explicitly says <code>phase_liquidity_verified=false</code>. Some closing orders fill over subsequent market bars; final-exit labels describe the aggregate position’s last exit and must not be interpreted as all shares trading at that one timestamp. Capacity-stress and real execution evidence remain necessary before deployment. The modeled 20bp sell tax, 2bp commission and 5bp slippage are assumptions of this comparison; this report does not certify them as the current legal or broker schedule.')
    body+=p('A real historical-context defect was found earlier: original OOS intraday context began on March 31, whereas IS had substantial preceding context. The corrected OOS generation restores 217 prior sessions of continuous history. It changes stored previous-session relative-volume and related metadata, but all 74 baseline candidate economics and all executions are identical; return remains −3.3276524383% and drawdown 29.1622440571%. Keep the correction for valid experiments, but do not attribute a nonexistent performance recovery to it.')
    body+=p('A separate feature limitation remains: the current-afternoon panel is built from only the current session, and <code>sector_intraday_rel_volume</code> equals 1.0 for all 356 selected IS candidate rows and all 74 OOS rows. The previous-session history repair does not repair that current-panel behavior. A causal rolling, same-cutoff volume denominator is a defensible separate experiment; it must use only prior complete sessions, preserve the decision cutoff, and produce a new source-bound generation. It is not yet a demonstrated explanation for the IS/OOS difference because the field is constant in both periods.')
    body+=p('IS begins on August 7 because of the shared harness’s KALCB policy evaluation schedule, rather than an OLR data-history lower bound. Earlier OLR snapshots exist, but changing the IS start after observing outcomes would change the question. The scored windows and flat-cash initialization stay fixed here. Daily lookback availability is adequate at both starts, and recorded incomplete-prefix exclusions are only 0.46% of IS and 0.42% of OOS eligible symbol-days. They do not explain the approximately 52% fall in final candidate supply.')
    body+='<h2>6. What the completed parameter experiments actually say</h2>'
    selected=[('ce14d8377b9e67ac6','Saved round 1'),('c1e5c4b5e26e960b8','Confirmation VWAP floor: 0% → −0.2%'),('ca18d9a35ba34c1cc','Position cap: 65% → 60%'),('cff804c36e3d4b7d0','Position cap: 65% → 52%'),('cbc2ce0bc6f49a9e3','Position cap: 65% → 50%'),('c8812a176b153deef','Delete cap: resolves to 25% default'),('ce0d97e2f019d24c1','Sector participation floor: 50% → 40%'),('cebe7162638f0c1b6','Remove score ≥650 branch'),('c15ba38c0b168ee51','Remove liquidity-only recycling restriction'),('cf5b8cc9d84d168ef','Disable MFE-fade activation'),('cd72a95a0fa95c30f','Restore historical VWAP-extension limit')]
    body+=table(['Variant','IS return','OOS return','IS Δ pp','OOS Δ pp','OOS DD'],[[label,f(byid[cid]['train_return_pct'])+'%',f(byid[cid]['oos_return_pct'])+'%',f(byid[cid]['train_gain_pp']),f(byid[cid]['oos_gain_pp']),f(byid[cid]['oos_drawdown_pct'])+'%'] for cid,label in selected])
    body+=p('The best previously completed near-preservation candidate is the −0.2% confirmation VWAP floor: OOS improves by 9.59pp to +6.27%, while IS falls by 3.64pp to +51.40%. That retains 97.65% of baseline terminal IS wealth, but only 93.38% of its IS profit; it narrowly misses the existing 3pp IS-return loss limit. It also leaves OOS drawdown at 27.97%, so it adds profitable opportunities without resolving the large-loss problem. “Material deterioration” should be judged against these explicit quantities, not changed retrospectively to admit a favored result.')
    v=support['c1e5c4b5e26e960b8']['oos']; top=v['contribution']
    body+=p(f'That VWAP change alters {top["changed_issuer_days"]} issuer-days, including subsequent path-dependent size differences. Its largest contribution is about ₩5.273 million on 2 April in 079550. The two best positive contributions account for {f(top["top2_positive_contribution_share"]*100)}% of positive attributed gains. Removing those contributions arithmetically still leaves +₩{f(top["delta_excluding_top2_positive_arithmetic_only"]/1e6,3)} million, but this is not a trade-deletion replay. Its five-session paired bootstrap interval for OOS uplift is approximately [{f(v["paired_block_bootstrap"]["5"]["ci95_pct_or_gain_pp"][0])}, {f(v["paired_block_bootstrap"]["5"]["ci95_pct_or_gain_pp"][1])}]pp, before accounting for strategy selection.')
    body+=p('The 60% cap preserves IS within 1.56pp but improves OOS by only 1.05pp and leaves a 28.22% drawdown. The 52% cap gains 3.91pp OOS but loses 4.21pp IS. The 25% default cap cuts the OOS drawdown to 15.11% and returns +7.58%, but sacrifices 30.31pp IS. These are valid causal sizing experiments showing that blanket de-risking pays a substantial opportunity cost. Removing the high-score branch similarly loses 18.54pp IS. It is not an acceptable general fix under the stated objective.')
    body+=p('The 40% sector-participation floor nearly reaches the existing economic gate: IS loses 2.94pp and OOS gains 1.92pp. Its OOS paired five-session bootstrap interval spans roughly −18.53pp to +23.52pp; the arithmetic gain turns negative after excluding its two best positive contributions. This is weak support for expanding admission indiscriminately. Restoring the historical wider entry-extension setting raises IS to +75.41% while worsening OOS to −14.58%: a clear example of why IS-only optimization is the wrong objective.')
    body+=p('Removing the dynamic middle-score overlay reproduces baseline account economics. Several historical exit leaves also have no realized effect because their activation conditions remain disabled. Deleting a setting may restore a default rather than remove a constraint; list positions also changed during historical rule additions. Experiments must be defined by resolved configuration and rule identity, with activation pairs, rather than by mutation labels alone. Identical outcomes are not independent supporting trials.')
    body+='<h2>7. The original selection has thin incremental support</h2>'
    body+=p('The saved “conditional capital recycling” overlay was explicitly retained as research-only. Its original support verdict failed <code>direct_support</code>: four issuer-day interventions, with fills above native quantity on only three of them. Its +4.246pp IS account improvement over its matched comparator was heavily concentrated in two February contributors of +2.187pp and +1.857pp. Those total about 95.24% of the net uplift, although other positive and negative path effects coexist. Under combined stress the overlay gain was +2.370pp, of which +2.110pp came from the largest contributor.')
    body+=p('This does not make every part of round 1 invalid, nor does it prove that all IS profit is overfit. It means the marginal overlay benefit was weakly supported before this OOS decline. The broader strategy also contains raw non-monotonic score intervals, a static sector prior, high concentration, and many previously explored settings. That search history creates selection risk. Keeping score branches because of a handful of realized winners, or inserting a cutoff just below a known loser’s score, would compound the problem.')
    body+=p('Formal research explains why the best result selected from many backtests has optimistic apparent performance: <a href="https://www.davidhbailey.com/dhbpapers/deflated-sharpe.pdf">Bailey and López de Prado, The Deflated Sharpe Ratio</a>; <a href="https://escholarship.org/uc/item/4w1110bb">Bailey et al., The Probability of Backtest Overfitting</a>. This report does not calculate a valid selection-adjusted significance level because the complete effective search and dependence structure are not reconstructed. No conventional bootstrap interval can substitute for that missing selection correction.')
    body+='<h2>8. The best-supported route toward the requested objective</h2>'
    body+=p('<strong>First preserve the economic comparison and repair measurement.</strong> Keep continuous causal source history, fixed date windows, complete daily marks, source hashes, retained fee assumptions and realistic delayed/partial fills. Publish the resolved policy rather than misleading rule names such as “lt300” when its actual maximum is 325. Distinguish exit trigger decisions from fill times and partial exit legs. The existing control has sufficient integrity for the conclusions here; source or execution failures encountered by other variants must remain excluded.')
    body+=p('<strong>Use the tested guards as the immediate research successor candidates.</strong> The 1.2R guard meets the requested OOS-improvement/IS-preservation objective on the specified historical windows, while the 0.8R guard offers stronger drawdown protection at a higher IS cost. Select between their recorded trade-offs before examining new validation outcomes. Any wider-entry combination is judged using its actual factorial results above. The next steps below are further hypotheses, not additional improvements already established by this review.')
    body+=p('<strong>Then address conditional concentration rather than simply shrinking every position.</strong> The evidence suggests preserving exposure where IS earned its profits while limiting capital-at-risk in sparse, weak or exceptionally volatile contexts. Research a simple size rule based on information available at entry: stop-distance/ATR, prior-data market breadth, number of qualified independent opportunities, and concentration across correlated sectors. For example, desired notional can be bounded by an equity risk budget divided by a conservative adverse-move estimate, subject to the original concentration and liquidity caps. The risk budget and adverse-move estimator require separate chronological calibration; no optimal numerical values are established here. A gap-risk reserve is necessary because a next-open exit cannot guarantee a threshold loss.')
    body+=p('<strong>Evaluate conditional loss containment alongside that sizing rule.</strong> The broad guard experiments above quantify the cost of intervening everywhere. If they sacrifice IS winners, a subsequent experiment should condition protection on a dated weak-market state or objectively poor follow-through, with the regime measured before the entry decision and held to a predeclared policy. Both major June losers were admitted in mixed/risk-off context and neither developed meaningful MFE. That is a mechanism hypothesis, not justification for a symbol blacklist or a rule keyed to their realized dates. Native replay must measure the winners such protection truncates as well as the losses it avoids.')
    body+=p('<strong>Recover opportunity through the least disruptive admission change.</strong> The small below-VWAP confirmation tolerance is more promising than broad score-band deletion: it materially raises OOS return while retaining most IS wealth, although it narrowly misses the strict return-preservation gate and still has a large drawdown. Test a small neighborhood around that existing setting, declared before results, with its single-change control. Combine it with a risk treatment only after measuring each component separately. Do not add single-run gains arithmetically: allocation, fills and reinvestment make the joint outcome non-additive.')
    body+=p('<strong>Separate market adaptation from data repair.</strong> A rolling current-afternoon relative-volume feature and uncertainty-aware sector breadth could improve regime sensitivity, especially as the median number of sector contributors falls from seven selected IS observations to three OOS. That is a new model experiment requiring complete historical panels and source-bound validation. Compare against the currently inert volume feature without simultaneously changing scores, bands and allocation. Avoid fitting new features exclusively to June.')
    body+=p('<strong>Prefer simpler score and allocation models unless complexity earns broad support.</strong> Compare raw momentum bands with a causally standardized or percentile-based score using only preceding data. Require added sector or rotation overlays to show incremental executed support across dates and issuers. Rank calibration should be tested against subsequent net payoff per unit of capital/risk, because positive average R or win rate did not protect the actual OOS account. Removing the working MFE-fade exit is contraindicated by the observed OOS deterioration when it is disabled.')
    body+='<h2>9. Acceptance and validation that match the objective</h2>'
    body+=p('The existing study’s economic gates provide a transparent working definition: IS return at least 52.0466% (no more than 3pp below baseline), OOS improvement at least 2pp (return at least −1.3277%), neither drawdown more than 2pp worse, and no reduction in executed trade count in either period. It additionally requires at least 97% of baseline terminal IS wealth; the 3pp return limit is stricter here. These are inherited research criteria, not a claim that the user explicitly chose those exact tolerances. The minimum OOS gate still permits a losing OOS account; a successful practical remedy should also aim for positive net performance and a substantial reduction in the 29.16% drawdown.')
    body+=p('The activity floor should remain a diagnostic of collapse, but the user’s central objective is performance, not maximizing trade count. A demonstrably safer and more profitable policy should not be discarded solely for fewer low-value trades. Any revision to that secondary criterion should be documented before further outcomes are inspected. Do not loosen IS-preservation tolerances after a promising OOS result appears.')
    body+=p('Use chronological outer validation: fit or select using only earlier data, apply an embargo appropriate to the strategy’s holding and feature horizons, and score the next contiguous block with causal feature history. Keep reset-account comparisons separate from a continuous deployment simulation that carries wealth, positions and capacity state. Do not stitch independently reset calendar segments and call the result a single account. Require parameter-neighborhood stability, broad intervention support, results without the two largest positive contributors as a diagnostic, and complete native replays at relevant account sizes.')
    body+=p('For any finalist, compare against a matched control under higher transaction costs, lower participation, auction nonfills/delays and no-upward-compounding. Report all attempted configurations, failed audits and dormant/aliased changes. The previously OOS April–July window has been inspected repeatedly; reserve genuinely unconsumed later data or prospective execution for the final generalization claim. This review did not consume later market outcomes.')
    body+=p('The baseline OOS five-session block bootstrap spans roughly −36.34% to +42.21%, widening to roughly −39.16% to +46.86% with ten-session blocks. The 47 position groups span only 29 entry dates; shared regimes and simultaneous holdings reduce independent information further. These are sensitivity distributions from historical daily returns, with a stationarity approximation, not probabilities of future profitability. Selection on these observations makes them particularly unsuitable as promotion confidence levels.')
    body+='<h2>10. Decision and evidence inventory</h2>'
    body+=p(f'<strong>{len(passing)} completed configurations satisfy all inherited acceptance gates under baseline execution assumptions.</strong> The selected guard narrowly misses the IS-preservation limit under combined execution stress. The evidence establishes several underlying mechanisms and useful trade-offs, but does not yet establish an optimal deployable correction. Retain the original round as the reference, keep the historical-context repair, and use the recorded 1.2R and 0.8R policies as concrete research candidates. Stronger execution robustness and independent chronological qualification remain outstanding. Canonical round and live configuration were not changed by this review.')
    body+=p(f'New work in this review: {new_audits} source-bound native replays with full audits; independent reconciliation of authenticated completed pairs; exact allocation/P&amp;L decomposition; monthly rejection/regime analysis; feature-variance checks; contribution and block-length sensitivity; and the report/figure. Earlier controls, ablations, continuity repair and original support verdict are reused evidence and are identified as such.')
    body+='<ul><li><a href="diagnostics.json">Derived diagnostics and bootstrap sensitivity</a></li><li><a href="comparisons.csv">All authenticated paired results (CSV)</a></li><li><a href="candidate_support.json">Candidate contribution and paired uncertainty</a></li><li><a href="excluded_trials.json">Excluded / unsupported / failed assessments</a></li><li><a href="provenance.json">Evidence hashes and source paths</a></li><li><a href="replays/registration.json">New loss-guard experiment registration</a></li><li><a href="replays/results.json">Six new full-audit replay results</a></li><li><a href="history_performance_attribution.json">Continuous-history repair: zero baseline P&amp;L change</a></li><li><a href="calendar_subperiods.json">Calendar NAV slices</a></li><li><a href="report.txt">Plain-text report</a></li></ul>'
    body+='<ul><li><a href="loss_guard_1p2_patch.yaml">Exact 1.2R research configuration patch</a></li><li><a href="loss_guard_1p2_research_candidate.json">Complete candidate mutation mapping</a></li><li><a href="replays/interaction_results.json">Adaptive interaction results</a></li><li><a href="replays/stress_results.json">Matched execution-stress results</a></li><li><a href="stress_authentication.json">Independent stress artifact authentication</a></li></ul>'
    body+='<details><summary>Full paired-result table</summary>'+table(['Configuration','IS %','OOS %','IS Δ pp','OOS Δ pp','IS DD %','OOS DD %','Trades IS/OOS','All gates'],[[x['label'],f(x['train_return_pct']),f(x['oos_return_pct']),f(x['train_gain_pp']),f(x['oos_gain_pp']),f(x['train_drawdown_pct']),f(x['oos_drawdown_pct']),f"{x['train_trades']}/{x['oos_trades']}",str(x['passes_registered_gates'])] for x in comps])+'</details>'
    css='body{font:17px/1.65 system-ui,sans-serif;color:#172033;background:#f3f5f9;margin:0}main{max-width:1080px;margin:32px auto;padding:44px 54px;background:white;border-radius:14px}h1{font-size:34px;line-height:1.2}h2{font-size:24px;margin-top:42px;color:#18457c}p{margin:18px 0}img{width:100%;margin:20px 0}a{color:#135baf}code{font-size:.88em;background:#edf1f8;padding:2px 5px}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.4}th,td{padding:10px;border-bottom:1px solid #d8e0ed;text-align:left;vertical-align:top}th{background:#eaf0f8}td:not(:first-child){font-variant-numeric:tabular-nums}.table{overflow-x:auto;margin:22px 0}details{margin-top:30px}summary{cursor:pointer;font-weight:700}@media(max-width:700px){main{margin:0;padding:22px}h1{font-size:28px}}@media print{body{background:white}main{margin:0;padding:0}h2{break-after:avoid}tr,img{break-inside:avoid}}'
    (ROOT/'report.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OLR round 1 OOS forensic review</title><style>'+css+'</style></head><body><main>'+body+'</main></body></html>',encoding='utf-8')
    class Plain(HTMLParser):
        def __init__(self):super().__init__();self.parts=[]
        def handle_data(self,data):self.parts.append(data)
        def handle_endtag(self,tag):
            if tag in ('p','h1','h2','tr','li','summary'):self.parts.append('\n\n')
            elif tag in ('td','th'):self.parts.append(' | ')
    plain=Plain();plain.feed(body)
    (ROOT/'report.txt').write_text(''.join(plain.parts),encoding='utf-8')
    print(json.dumps({'html':str(ROOT/'report.html'),'text_words':len(''.join(plain.parts).split()),'paired_configurations':len(comps),'passing':len(passing)}))


